{"content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Job Corpus Architecture — Sourov Deb</title>
<style>
  :root {
    --bg: #0f1419;
    --card: #1a2332;
    --border: #2d3a4f;
    --text: #e7ecf3;
    --muted: #8b9bb4;
    --accent: #3b82f6;
    --keep: #22c55e;
    --archive: #f59e0b;
    --drop: #ef4444;
    --l0: #6366f1;
    --l1: #22c55e;
    --l2: #06b6d4;
    --l3: #a855f7;
    --l4: #94a3b8;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0; font-family: "Segoe UI", system-ui, sans-serif;
    background: var(--bg); color: var(--text); line-height: 1.45;
    padding: 24px;
  }
  h1 { font-size: 1.4rem; margin: 0 0 4px; }
  .sub { color: var(--muted); font-size: 0.9rem; margin-bottom: 24px; }
  .grid { display: grid; gap: 16px; }
  .layers { display: grid; gap: 12px; }
  .layer {
    border: 1px solid var(--border); border-radius: 12px;
    background: var(--card); padding: 14px 16px;
  }
  .layer h2 {
    margin: 0 0 8px; font-size: 0.85rem; letter-spacing: 0.04em;
    text-transform: uppercase; display: flex; align-items: center; gap: 8px;
  }
  .pill {
    display: inline-block; padding: 2px 8px; border-radius: 999px;
    font-size: 0.7rem; font-weight: 600; color: #fff;
  }
  .l0 .pill { background: var(--l0); }
  .l1 .pill { background: var(--l1); }
  .l2 .pill { background: var(--l2); }
  .l3 .pill { background: var(--l3); }
  .l4 .pill { background: var(--l4); color: #0f1419; }
  .files { display: flex; flex-wrap: wrap; gap: 8px; }
  .file {
    border: 1px solid var(--border); border-radius: 8px;
    padding: 8px 10px; font-size: 0.78rem; background: #121a24;
    min-width: 180px; max-width: 280px;
  }
  .file strong { display: block; font-size: 0.8rem; margin-bottom: 2px; }
  .meta { color: var(--muted); font-size: 0.72rem; }
  .tag-keep { color: var(--keep); }
  .tag-arch { color: var(--archive); }
  .tag-drop { color: var(--drop); }
  .two { display: grid; grid-template-columns: 1.2fr 1fr; gap: 16px; }
  @media (max-width: 900px) { .two { grid-template-columns: 1fr; } }
  table { width: 100%; border-collapse: collapse; font-size: 0.82rem; }
  th, td { border-bottom: 1px solid var(--border); padding: 8px; text-align: left; }
  th { color: var(--muted); font-weight: 600; }
  .note {
    border-left: 3px solid var(--accent); padding: 10px 12px;
    background: #121a24; border-radius: 0 8px 8px 0; font-size: 0.85rem;
    margin-top: 16px; color: var(--muted);
  }
  .flow {
    display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
    margin: 16px 0; font-size: 0.85rem;
  }
  .flow .box {
    background: var(--card); border: 1px solid var(--border);
    padding: 10px 14px; border-radius: 8px;
  }
  .arrow { color: var(--muted); }
  code { font-size: 0.78rem; background: #0b1016; padding: 1px 5px; border-radius: 4px; }
</style>
</head>
<body>
  <h1>Job corpus architecture</h1>
  <p class="sub">Sourov Deb · audited 2026-09-05 · evidence: <code>_AUDIT_deep_20260905.json</code> · agent entry: <code>00_CORPUS_OFFICIAL/MANIFEST.json</code></p>

  <div class="flow">
    <div class="box">Collect (FT API + lists + APIs)</div>
    <span class="arrow">→</span>
    <div class="box">L0 FULL 4288 / profiles 620</div>
    <span class="arrow">→</span>
    <div class="box">L1 CORE 719 / PM 1000</div>
    <span class="arrow">→</span>
    <div class="box">L2 geo slices</div>
    <span class="arrow">→</span>
    <div class="box">L3 contacts 88</div>
    <span class="arrow">→</span>
    <div class="box">Apply / email (not CSV dump)</div>
  </div>

  <div class="two">
    <div class="layers">
      <section class="layer l0">
        <h2><span class="pill">L0</span> Raw corpus — keep</h2>
        <div class="files">
          <div class="file"><strong>JOBS_COMPANIES_FULL</strong><span class="meta">4288 rows · 2235 cos · live_offer 3046</span></div>
          <div class="file"><strong>COMPANY_PROFILES</strong><span class="meta">620 rows (not 1000) · blurb ≤400ch</span></div>
          <div class="file"><strong>INTL_TEACHING_APIS</strong><span class="meta">73 rows</span></div>
        </div>
      </section>
      <section class="layer l1">
        <h2><span class="pill">L1</span> Profile shortlists — apply seeds</h2>
        <div class="files">
          <div class="file"><strong>SOUROV_CORE_…</strong><span class="meta tag-keep">719 · preferred shortlist</span></div>
          <div class="file"><strong>SOUROV_PROFILE_MATCHED</strong><span class="meta">1000 · 555 are company_profile rows</span></div>
          <div class="file"><strong>CELTA+SOCIAL+HANDICAP</strong><span class="meta">1064</span></div>
        </div>
      </section>
      <section class="layer l2">
        <h2><span class="pill">L2</span> Geo / tier slices</h2>
        <div class="files">
          <div class="file"><strong>SOurovision_974</strong><span class="meta">758</span></div>
          <div class="file"><strong>SOurovision_FR</strong><span class="meta">436</span></div>
          <div class="file"><strong>974_CELTA_ELT_QUEUE</strong><span class="meta">433</span></div>
          <div class="file"><strong>FR / EU / DOM / INTL / translator / social</strong><span class="meta">thin views</span></div>
        </div>
      </section>
      <section class="layer l3">
        <h2><span class="pill">L3</span> Contacts</h2>
        <div class="files">
          <div class="file"><strong>CONTACTS_COMPREHENSIVE</strong><span class="meta tag-keep">88 emails</span></div>
          <div class="file"><strong>CONTACTS_COMPILED</strong><span class="meta">33</span></div>
          <div class="file"><strong>EMAIL_QUEUE</strong><span class="meta">18</span></div>
        </div>
      </section>
      <section class="layer l4">
        <h2><span class="pill">L4</span> Audit + official pack</h2>
        <div class="files">
          <div class="file"><strong>FUNNEL_AUDIT</strong><span class="meta">1324</span></div>
          <div class="file"><strong>00_CORPUS_OFFICIAL/*</strong><span class="meta">INDEX · MANIFEST · SCHEMA</span></div>
        </div>
      </section>
    </div>

    <div>
      <section class="layer">
        <h2>Archive / do not query as apply queue</h2>
        <table>
          <thead><tr><th>File</th><th>Rows</th><th>Why</th></tr></thead>
          <tbody>
            <tr><td>SOUROV_JOBS_FINAL</td><td>7880</td><td class="tag-arch">80% blank geo/tiers</td></tr>
            <tr><td>MASTER_JOB_DATABASE</td><td>7440</td><td class="tag-arch">noisy 65-col merge</td></tr>
            <tr><td>JOBS_COMPANIES_1000_MIXED</td><td>1000</td><td class="tag-arch">⊂ FULL</td></tr>
            <tr><td>SKYVERN_QUEUE</td><td>1219</td><td class="tag-arch">contacts ≠ offers</td></tr>
            <tr><td>test_filter_output</td><td>61</td><td class="tag-drop">dup of MASTER_FILTERED</td></tr>
            <tr><td>OUTREACH_974 / SKYVERN_FILTERED</td><td>0</td><td class="tag-drop">empty shells</td></tr>
          </tbody>
        </table>
      </section>

      <section class="layer" style="margin-top:16px">
        <h2>Company “what they do” quality</h2>
        <table>
          <tbody>
            <tr><td>Profile rows</td><td>620 / 620 text non-empty</td></tr>
            <tr><td>True edu/lang signal in text</td><td>~63 only</td></tr>
            <tr><td>Very short (&lt;40 ch)</td><td>102 (incl. image URLs)</td></tr>
            <tr><td>Hard cap</td><td>max 400 characters</td></tr>
            <tr><td>Verdict</td><td>Classification OK · encyclopedia NO</td></tr>
          </tbody>
        </table>
      </section>

      <section class="layer" style="margin-top:16px">
        <h2>Relevance (profile types)</h2>
        <table>
          <tbody>
            <tr><td class="tag-keep">High</td><td>language_school, education, CFA, LSP (~170)</td></tr>
            <tr><td class="tag-arch">Adjacent</td><td>NGO, public, social, health (~60)</td></tr>
            <tr><td class="tag-drop">Noise</td><td>hospitality, retail, food, temp (~180+)</td></tr>
          </tbody>
        </table>
      </section>
    </div>
  </div>

  <p class="note">
    <strong>Agent rule:</strong> Read <code>MANIFEST.json</code> first. Only <code>role=apply_candidate</code> or <code>role=contact</code> may enter pipelines.
    FT detail URLs remain login-wall (neo), not Camoufox. Counts are DictReader facts — filenames lie (<code>1000</code> profiles = 620 companies).
  </p>
</body>
</html>
