# Save web results
with open(CONTACTS / "EMAIL_WEB_PROBE_RESULTS_20260905.json", "w", encoding="utf-8") as f:
    json.dump(results_web, f, indent=2, ensure_ascii=False)

got = [r for r in results_web if r.get("emails")]
print(f"\nDomains with emails: {len(got)} / {len(jobs)}")
for r in got:
    print(f"  {r['name_raw'][:40]:40} {r['emails']}")
