            for enc in ("utf-8", "latin-1", "cp1252"):
                try:
                    return raw.decode(enc), resp.status
                except Exception:
                    continue
            return raw.decode("utf-8", errors="replace"), resp.status
    except Exception as ex:
        return None, str(ex)[:80]


def extract_emails(html: str):
    found = set()
    if not html:
        return found
    for m in re.findall(r"mailto:([^\s\"'?#>]+)", html, re.I):
        e = norm_email(m)
        if e:
            found.add(e)
    # de-obfuscate simple [at] patterns
    html2 = re.sub(r"\s*\[at\]\s*", "@", html, flags=re.I)
    html2 = re.sub(r"\s*\(at\)\s*", "@", html2, flags=re.I)
    html2 = re.sub(r"\s*\[dot\]\s*", ".", html2, flags=re.I)
    for m in EMAIL_RE.findall(html2):
        e = norm_email(m)
        if e:
            found.add(e)
    return found


def probe_domain(domain, name_key, name_raw, tier):
    domain = domain.strip().lower().removeprefix("www.")
    emails = set()
    pages_ok = 0
    tried = 0
    for scheme in ("https", "http"):
        base = f"{scheme}://{domain}"
        for path in PATHS:
            tried += 1
            html, meta = fetch(base + path)
            if html and len(html) > 150:
                pages_ok += 1
                got = extract_emails(html)
                # prefer same-domain emails
                same = {e for e in got if domain.split(":")[0] in e.split("@")[-1] or domain in e}
                emails |= (same or got)
                if emails and path != "":
                    break
            if tried >= 6 and emails:
                break
        if emails or pages_ok:
            break
    return {
        "name_key": name_key,
        "name_raw": name_raw,
        "final_tier": tier,
        "domain": domain,
        "emails": sorted(emails),
        "pages_ok": pages_ok,
        "tried": tried,
    }


def main():
    pri = list(csv.DictReader(open(CONTACTS / "EMAIL_RECON_WEB_PRIORITY_20260905.csv", encoding="utf-8")))
    jobs = []
    seen = set()
    for r in pri:
        for d in (r.get("domains") or "").split(";"):
            d = d.strip().lower().removeprefix("www.")
            if not d or d in seen or "." not in d:
                continue
            seen.add(d)
            jobs.append((d, r["name_key"], r["name_raw"], r.get("final_tier", "")))

    print(f"START jobs={len(jobs)}", flush=True)
    results = []
    t0 = time.time()
    with ThreadPoolExecutor(max_workers=12) as ex:
        futs = {ex.submit(probe_domain, *j): j for j in jobs}
        done = 0
        for fut in as_completed(futs):
            done += 1
            try:
                res = fut.result()
            except Exception as e:
                d, k, n, t = futs[fut]
                res = {"name_key": k, "name_raw": n, "final_tier": t, "domain": d, "emails": [], "error": str(e)}
            results.append(res)
            if done % 15 == 0 or res.get("emails"):
                print(
                    f"[{done}/{len(jobs)}] {res.get('name_raw','')[:34]:34} "
                    f"{res.get('domain','')[:28]:28} e={res.get('emails')}",
                    flush=True,
                )
            if done % 20 == 0:
                OUT_PROG.write_text(json.dumps({"done": done, "total": len(jobs), "hits": sum(1 for r in results if r.get('emails'))}, indent=2), encoding="utf-8")
                OUT_JSON.write_text(json.dumps(results, indent=2, ensure_ascii=False), encoding="utf-8")

    OUT_JSON.write_text(json.dumps(results, indent=2, ensure_ascii=False), encoding="utf-8")
    hits = [r for r in results if r.get("emails")]
    summary = {
        "total_domains": len(jobs),
        "with_emails": len(hits),
        "elapsed_s": round(time.time() - t0, 1),
        "hits": [{"name": r["name_raw"], "domain": r["domain"], "emails": r["emails"], "tier": r.get("final_tier")} for r in hits],
    }
    (CONTACTS / "EMAIL_WEB_PROBE_SUMMARY_20260905.json").write_text(json.dumps(summary, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"DONE hits={len(hits)}/{len(jobs)} elapsed={summary['elapsed_s']}s", flush=True)
    for h in hits:
        print(f"  HIT {h['name_raw'][:40]} -> {h['emails']}", flush=True)


if __name__ == "__main__":
    main()
