BAD = {
    "none", "n/a", "na", "null", "votre@email.fr", "email@email.com", "test@test.com",
    "example@example.com", "nom@domaine.fr", "prenom.nom@entreprise.fr",
    "photo_agence_1@1920x1248.jpg", "user@domain.com", "name@company.com", "contact@domain.com",
}
BAD_SUFFIX = (".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".css", ".js")
BAD_LOCAL = {"noreply", "no-reply", "mailer-daemon", "postmaster"}
SKIP_APPLICANT = {"sourovdeb.is@gmail.com"}

def norm_email(e: str):
    e = (e or "").strip().lstrip("%20").strip().lower().strip(".,;:()[]<>\"'")
    if not e or e in BAD or e in SKIP_APPLICANT:
        return None
    if any(e.endswith(s) for s in BAD_SUFFIX):
        return None
    if not EMAIL_RE.fullmatch(e):
        m = EMAIL_RE.search(e)
        if not m:
            return None
        e = m.group(0).lower()
    local = e.split("@")[0]
    if local in BAD_LOCAL or local.startswith("noreply"):
        return None
    if any(x in e for x in ("sentry", "wixpress", "example.", "@domain.com")):
        return None
    if re.search(r"@\d+x\d+", e):
        return None
    return e

def quality(email: str):
    local = email.split("@")[0]
    generics = ("contact", "info", "accueil", "reception", "rh", "recrutement", "emploi",
                "job", "jobs", "carrieres", "careers", "admin", "hello", "office", "direction",
                "secretariat", "communication", "commercial", "formation")
    score = 100
    if any(g in local for g in generics):
        score -= 35
    if "." in local and not local.startswith("info"):
        score += 10
    return max(0, min(100, score))

def company_key_variants(name: str):
    n = (name or "").strip().lower()
    yield n
    n2 = re.sub(r"\b(sa|sas|sarl|eurl|sci|sasu|se|ltd|llc|inc|gmbh|plc)\b\.?", "", n)
    n2 = re.sub(r"[^\w\s]", " ", n2)
    n2 = re.sub(r"\s+", " ", n2).strip()
    yield n2

